<template>
  <div class="detail-back"><router-link to="/requests">← 返回申请列表</router-link><el-button link @click="load" :loading="loading">刷新状态</el-button></div>
  <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb20" />
  <div v-loading="loading" v-if="item" class="request-detail"><div class="page-heading"><div><span class="eyebrow">LOAN REQUEST / 借用申请单</span><h1>{{ item.number }}</h1><p>{{ item.category_name }} · 一台设备 · {{ item.store_name }}</p></div><div class="detail-status"><StatusPill :status="item.status" /><el-tag v-if="item.overdue" type="danger" effect="plain">逾期未归还</el-tag></div></div>
    <div v-if="item.status === 'rejected' || item.status === 'withdrawn'" class="context-note"><Icon name="help" /> 这张申请已结束，历史记录保留。如仍有需要，请重新发起一张借用申请。</div>
    <div class="detail-layout"><div><section class="panel detail-info"><div class="panel-heading"><h3>借用信息</h3><span class="muted">{{ dateTime(item.created_at) }} 创建</span></div><dl class="info-grid"><div><dt>申请人</dt><dd>{{ item.applicant_name }}</dd></div><div><dt>所属门店</dt><dd>{{ item.store_name }}</dd></div><div><dt>设备类别</dt><dd>{{ item.category_name }}</dd></div><div><dt>预计归还</dt><dd :class="{ 'danger-text': item.overdue }">{{ day(item.due_date) }}</dd></div><div class="wide"><dt>业务用途</dt><dd class="pre-wrap">{{ item.purpose }}</dd></div></dl><div class="assigned-device"><div class="device-icon"><Icon name="box" /></div><div><small>实际分配设备</small><strong>{{ item.asset_code || '尚未分配' }}</strong></div><span>{{ item.asset_code ? '请当面核对设备编号' : '由设备管理员在发放时选择' }}</span></div></section>
      <section class="panel action-panel"><div class="panel-heading"><div><h3>下一步操作</h3><p>{{ stageHint }}</p></div></div><div class="action-buttons"><el-button v-if="item.status === 'draft' && session.user?.role === 'employee'" @click="openEdit">编辑草稿</el-button><el-button v-for="action in (item.available_actions || []).filter(action => action !== 'edit')" :key="action" :type="['reject','withdraw','undo_issue'].includes(action) ? 'default' : 'primary'" @click="openAction(action)">{{ actions[action] || action }}</el-button><div v-if="!(item.available_actions || []).length" class="no-action"><Icon name="clock" /><span>当前账号没有可执行的操作。请等待相应角色处理。</span></div></div></section>
    </div><section class="panel timeline-panel"><div class="panel-heading"><h3>流转记录</h3><span class="count-badge">{{ (item.events || []).length }}</span></div><div v-if="!(item.events || []).length" class="empty-inline">草稿尚未提交，暂无流转记录。</div><ol class="event-timeline"><li v-for="(event, index) in [...(item.events || [])].reverse()" :key="event.id || index"><span class="event-dot"></span><div class="event-title">{{ event.label || actions[event.action] || event.action }}</div><p>{{ event.actor_name }}<span> · {{ dateTime(event.created_at) }}</span></p><div v-if="event.reason" class="event-reason">{{ event.reason }}</div><small v-if="event.to_status">{{ requestStates[event.to_status] || event.to_status }}</small></li></ol></section></div>
  </div>
  <el-empty v-else-if="!loading && !error" description="申请不存在或当前账号无权查看" />
  <el-dialog v-model="acting" :title="actions[currentAction]" width="520px" :close-on-click-modal="false"><p class="dialog-intro">{{ actionHint }}</p><el-form ref="actionRef" :model="actionForm" label-position="top"><el-form-item v-if="currentAction === 'issue'" label="选择发放设备" prop="asset_id" :rules="[{ required: true, message: '请选择设备', trigger: 'change' }]"><el-select v-model="actionForm.asset_id" placeholder="请选择同类别的空闲设备" class="full-width" :loading="assetsLoading"><el-option v-for="asset in availableAssets" :key="asset.id" :value="asset.id" :label="`${asset.code} · ${asset.name}`" /></el-select><div v-if="!assetsLoading && !availableAssets.length" class="field-note danger-text">暂无可发放设备。可以关闭此窗口，待设备归还后再处理。</div></el-form-item><el-form-item v-if="currentAction === 'inspect'" label="设备检查结果"><el-radio-group v-model="actionForm.condition"><el-radio value="normal">检查正常，恢复可用</el-radio><el-radio value="damaged">存在异常，进入待维修</el-radio></el-radio-group></el-form-item><el-form-item :label="reasonRequired ? '处理说明（必填）' : '处理说明（选填）'" prop="reason" :rules="reasonRequired ? [{ required: true, whitespace: true, message: '请填写具体原因或检查发现', trigger: 'blur' }] : []"><el-input v-model="actionForm.reason" type="textarea" :rows="3" maxlength="1000" show-word-limit placeholder="说明交接情况或处理原因，方便后续追溯。" /></el-form-item></el-form><template #footer><el-button @click="acting = false">取消</el-button><el-button type="primary" :loading="saving" @click="confirmAction">{{ currentAction === 'receive' ? '确认签收' : '确认' + actions[currentAction] }}</el-button></template></el-dialog>
  <el-dialog v-model="editing" title="编辑借用草稿" width="520px" :close-on-click-modal="false"><el-form ref="editRef" :model="editForm" label-position="top"><el-form-item label="设备类别" prop="category_id" :rules="[{ required: true, message: '请选择类别' }]"><el-select v-model="editForm.category_id" class="full-width"><el-option v-for="category in categories" :key="category.id" :label="category.name" :value="category.id" /></el-select></el-form-item><el-form-item label="业务用途" prop="purpose" :rules="[{ required: true, whitespace: true, message: '请填写用途' }]"><el-input v-model="editForm.purpose" type="textarea" :rows="3" maxlength="500" /></el-form-item><el-form-item label="预计归还日期" prop="due_date" :rules="[{ required: true, message: '请选择归还日期' }]"><el-date-picker v-model="editForm.due_date" type="date" value-format="YYYY-MM-DD" /></el-form-item></el-form><template #footer><el-button @click="editing = false">取消</el-button><el-button type="primary" :loading="saving" @click="saveDraft">保存修改</el-button></template></el-dialog>
</template>
<script setup>
import { computed, ref, reactive, onMounted } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { useSession } from '../stores/session'
import { get, post, patch, rows, report } from '../api/client'
import { actions, requestStates, dateTime, day } from '../utils/format'
import StatusPill from '../ui/StatusPill.vue'
import Icon from '../ui/Icon.vue'
const route = useRoute(), session = useSession(), item = ref(null), loading = ref(false), error = ref(''), acting = ref(false), editing = ref(false), currentAction = ref(''), saving = ref(false), actionRef = ref(), editRef = ref(), assetsLoading = ref(false), availableAssets = ref([]), categories = ref([])
const actionForm = reactive({ reason: '', asset_id: null, condition: 'normal' }), editForm = reactive({ category_id: null, purpose: '', due_date: '' })
const reasonRequired = computed(() => ['reject', 'undo_issue'].includes(currentAction.value) || (currentAction.value === 'inspect' && actionForm.condition === 'damaged'))
const stageHint = computed(() => ({ draft: '检查借用信息后提交，店长将收到待审批事项。', pending: '等待所属门店店长确认业务需要。', approved: '审批通过，等待设备管理员分配具体设备。', handover: '已登记发放，申请人需当面核对设备并确认签收。', borrowed: '设备已签收，请在预计归还日期前完成归还。', return_pending: '等待设备管理员确认设备已收到并完成检查。', returned: '本次借用已完成，设备状况已登记。', rejected: '店长已驳回，处理原因保留在流转记录中。', withdrawn: '申请已撤回，历史记录仍可查询。' }[item.value?.status] || ''))
const actionHint = computed(() => ({ submit: '提交后借用信息将锁定，等待所属门店店长审批。', approve: '确认该申请的用途及借期合理。通过后由设备管理员发放。', reject: '请填写驳回原因，帮助申请人了解需要调整的内容。', withdraw: '撤回将结束这张申请。如仍有需要，可重新发起。', issue: '仅可选择同类别且当前空闲的设备。实际发放前请核对编号。', undo_issue: '仅在待签收阶段可撤销，请确认已收回实际设备。', receive: '请确认已经收到该编号设备，并核对外观与基本功能。', return: '请先按约定交回设备，再发起归还验收。设备在验收完成前仍处于占用状态。', inspect: '请确认实际收到设备并完成检查。异常设备将进入待维修，不能再次发放。' }[currentAction.value] || ''))
async function load() { loading.value = true; error.value = ''; try { item.value = await get(`requests/${route.params.id}/`) } catch (e) { error.value = e.userMessage; item.value = null } finally { loading.value = false } }
async function openAction(action) {
  currentAction.value = action; actionForm.reason = ''; actionForm.asset_id = null; actionForm.condition = 'normal'; acting.value = true
  if (action === 'issue') { assetsLoading.value = true; try { availableAssets.value = rows(await get('assets/', { status: 'available', category_id: item.value.category_id, page_size: 100 })) } catch (e) { report(e) } finally { assetsLoading.value = false } }
}
async function confirmAction() {
  if (saving.value || !await actionRef.value.validate().catch(() => false)) return
  saving.value = true
  try { await post(`requests/${item.value.id}/${currentAction.value}/`, { ...actionForm }); acting.value = false; ElMessage.success('操作已完成，流转记录已更新。'); await load() }
  catch (e) { report(e); if ([403, 409].includes(e.response?.status)) { acting.value = false; await load() } }
  finally { saving.value = false }
}
async function openEdit() { Object.assign(editForm, { category_id: item.value.category_id, purpose: item.value.purpose, due_date: item.value.due_date }); editing.value = true; try { categories.value = rows(await get('categories/')) } catch (e) { report(e) } }
async function saveDraft() { if (saving.value || !await editRef.value.validate().catch(() => false)) return; saving.value = true; try { await patch(`requests/${item.value.id}/`, editForm); editing.value = false; ElMessage.success('草稿已更新。'); await load() } catch (e) { report(e) } finally { saving.value = false } }
onMounted(load)
</script>
